import { WifiOff } from 'lucide-react';

interface EmptyStateProps {
  reason: string;
  onRetry?: () => void;
}

export function EmptyState({ reason, onRetry }: EmptyStateProps) {
  return (
    <div
      role="status"
      aria-live="polite"
      className="flex flex-col items-center justify-center rounded-xl border border-dashed border-border bg-card/50 p-8 text-center"
    >
      <WifiOff className="mb-2 h-6 w-6 text-text-muted" aria-hidden="true" />
      <p className="text-sm font-semibold text-text-primary">{reason}</p>
      {onRetry && (
        <button
          onClick={onRetry}
          className="mt-3 rounded-lg bg-optimized px-3 py-1.5 text-xs font-semibold text-white transition-colors hover:opacity-90"
        >
          Retry
        </button>
      )}
    </div>
  );
}